import org.gradle.api.plugins.quality.Checkstyle

gradle.projectsEvaluated {
    def root = gradle.rootProject
    def paths = new File('/tmp/simplepoint-resource-generations-style-files.txt').readLines().collect { root.file(it) }
    def checks = []
    root.allprojects.each { p ->
        def sources = paths.findAll { it.toPath().startsWith(p.projectDir.toPath().resolve('src')) }
        if (!sources.isEmpty()) {
            checks.add(p.tasks.register('checkstyleResourceGenerations', Checkstyle) {
                source sources
                classpath = p.sourceSets.test.compileClasspath
                configFile = root.file('checkstyle/google_checks.xml')
                maxWarnings = 0
                reports {
                    xml.required = true
                    html.required = true
                }
            })
        }
    }
    root.tasks.register('verifyResourceGenerationsStyle') { dependsOn checks }
}

